questionvariables.text:
/* Paramètres du signal affiché */
osc_fq: stackunits(500, Hz);
fq_unit : stack_units_units(osc_fq);
fq_nums :stack_units_nums(osc_fq);
T_unit : stack_unit_si_to_si_base(1/fq_unit);
T_nums: 1/fq_nums ;
T:stackunits(T_nums, T_unit);
osc_um: 3;
unit_osc_um:V;
precision_T:0.05;
ti: 9; /* Indice temps/div par défaut */
si: 7; /* Indice volt/div par défaut */

/* Réponses attendues */

ta_T:(T);
ta_f: osc_fq;

feedbackvariables.text:
/* --- Traitement Période T --- */
           stud_si_T : stack_unit_si_to_si_base(ans_T);
           teach_si_T : T_unit;
           v_pure_e_T : subst(map(lambda([u], u=1), listofvars(stud_si_T)), stud_si_T);
           v_pure_t_T : subst(map(lambda([u], u=1), listofvars(teach_si_T)), teach_si_T);
           eleve_unit_T : 2 * stud_si_T / v_pure_e_T;
           teacher_unit_T : 2 * teach_si_T / v_pure_t_T;

           /* --- Traitement Fréquence f --- */
           stud_si_f : stack_unit_si_to_si_base(ans_f);
           teach_si_f : fq_unit;
           v_pure_e_f : subst(map(lambda([u], u=1), listofvars(stud_si_f)), stud_si_f);
           v_pure_t_f : subst(map(lambda([u], u=1), listofvars(teach_si_f)), teach_si_f);
           eleve_unit_f : 2 * stud_si_f / v_pure_e_f;
           teacher_unit_f : 2 * teach_si_f / v_pure_t_f;
